class Solution:
    def longestValidSubstring(self, word: str, forbidden: List[str]) -> int:
        forb = set(forbidden)
        n = len(word)
        left = 0
        best = 0
        for r in range(n):
            for L in range(1, 11):
                s = r - L + 1
                if s < 0:
                    break
                if s < left:
                    break
                if word[s:r+1] in forb:
                    left = s + 1
                    break
            # Taking the smallest-start-forbidden check: the first match found
            # (shortest length) gives the largest s; need max over all matches.
            best = max(best, r - left + 1)
        return best
